css:
.row{display:flex; align-items:flex-start; gap:22px}
.row>li:nth-child(1){height:145px; margin-top:0}
.row>li:nth-child(2){height:180px; margin-top:12px}
.row>li:nth-child(3){height:145px; margin-top:33px}
.row>li:nth-child(4){height:180px; margin-top:47px}
/* 実物写真の見立てにする場合 */
.pic{border:8px solid #e7ddc9; box-shadow:0 3px 8px rgba(0,0,0,.18)}
.pic:nth-child(odd){transform:rotate(-5deg)} .pic:nth-child(even){transform:rotate(3deg)}
